import{_ as a,o as t,a as i,b as r}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"AIC和AIV独立运行机制","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/aic_aiv_independent_execution"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/aic_aiv_independent_execution.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/aic_aiv_independent_execution.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),_={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/aic_aiv_independent_execution.md"};function l(n,e,o,c,p,s){return t(),i("div",null,[...e[0]||(e[0]=[r(`<div><article class="markdown-body"><h1>AIC和AIV独立运行机制<span id="ZH-CN_TOPIC_0000002532388137"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002299608693_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>AIC和AIV独立运行机制，又称双主模式。在<a href="../../../../programming_guide/advanced_programming/hardware_implementation/basic_architecture.html#li188191010204418">分离模式</a>下，区别于MIX模式（包含矩阵计算和矢量计算）通过消息机制驱动AIC运行，双主模式为AIC和AIV独立运行代码，不依赖消息驱动，开启双主模式能够提高Matmul计算性能。默认情况下，双主模式不开启，需要通过MatmulConfig中的enableMixDualMaster参数开启。</p><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002299608693_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>算子中的矩阵计算和矢量计算相关代码独立运行，不依赖消息驱动时，可以开启双主模式，以提高Matmul计算性能。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002299608693_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>该功能仅支持<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulConfig.html">Norm模板</a>和<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulConfig.html">MDL模板</a>。</li><li>算子核函数（Kernel）的类型为MIX，同时AIC核数 : AIV核数为1:1。</li><li>算子核函数（Kernel）的类型为MIX，同时AIC核数 : AIV核数为1:2，且A矩阵和B矩阵同时开启<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_usage.html">IBSHARE</a>参数。</li><li>同一算子中所有Matmul对象的该参数取值必须保持一致。</li><li>A、B、Bias矩阵只支持从Global Memory输入。</li><li>获取矩阵计算结果只支持调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateAll.html">IterateAll</a>接口输出到<a href="../../../../../api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor.html">GlobalTensor</a>，即计算结果放置于Global Memory的地址，不能调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetTensorC.html">GetTensorC</a>等接口获取结果。</li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002299608693_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_mixdualmaster">开启双主模式的算子样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 修改模板参数enableMixDualMaster=true，Norm模板开启双主模式，MDL模板使用GetMDLConfig接口获取模板参数。
constexpr static MatmulConfig MM_CFG = GetNormalConfig(false, false, false, BatchMode::BATCH_LESS_THAN_L1, true, IterateOrder::ORDER_M, ScheduleType::OUTER_PRODUCT, false, true/*enableMixDualMaster*/);
Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;

// 常规Matmul计算
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);
mm.SetTensorA(gm_a);
mm.SetTensorB(gm_b);
mm.SetBias(gm_bias);
mm.IterateAll(gm_c);
</code></pre></div></article></div>`,1)])])}const u=a(_,[["render",l]]);export{m as __pageData,u as default};
